"""Editorial blog expansion of the owner's 30-day social campaign."""
from pathlib import Path
import json
DATA=json.loads((Path(__file__).resolve().parents[1]/'data/social_campaign.json').read_text())
DAYS=DATA['days']
VI=[
('Làm quen Stay in Da Nang: bắt đầu lên kế hoạch Việt Nam','Chọn một vùng làm trọng tâm trước khi đặt dịch vụ. Với chuyến đi ngắn, Đà Nẵng có thể là điểm xuất phát cho những ngày khám phá biển, Hội An hoặc Huế; mỗi điểm cần được sắp lịch riêng, không mặc định có thể đi hết trong một ngày.','Lưu các điểm muốn ghé lên bản đồ, rồi so sánh chỗ ở và phương tiện theo ngày thực tế. Website cung cấp ý tưởng và link đối tác; đặt phòng, thanh toán và xác nhận dịch vụ được xử lý trên Trip.com.'),
('Sáu cách khám phá Việt Nam: lưu trú, tour và phương tiện','Một hành trình có thể kết hợp nơi ở, trải nghiệm có hướng dẫn, chuyến bay, ô tô, đường sắt và thời gian tự khám phá. Chọn dịch vụ theo nhu cầu, thay vì đặt tất cả chỉ vì chúng xuất hiện trong một danh sách.','So sánh tổng thời gian và chi phí giữa các chặng. Với tàu hỏa, kiểm tra nhà ga, tuyến và loại chỗ bằng thông tin của đơn vị bán vé. Link Trip.com chung không có nghĩa tuyến tàu hoặc khung giờ đã được chọn sẵn.'),
('Vì sao chọn Đà Nẵng cho chuyến khám phá miền Trung?','Đà Nẵng có thể kết hợp những buổi dạo biển, ăn uống và khám phá khu vực sông Hàn. Hội An và Huế là các chuyến đi riêng cần tính thời gian di chuyển, thời tiết và sức khỏe của nhóm.','Chọn chỗ ở theo hoạt động ưu tiên: gần tuyến đi bộ ra biển, thuận tiện lịch hẹn trong thành phố hoặc hợp chặng đi xa. Kiểm tra địa chỉ và đường đi thực tế thay vì chỉ dựa vào ảnh bìa hay tên khách sạn.'),
('Checklist trước chuyến đi Việt Nam: giấy tờ, lịch trình và đặt dịch vụ','Kiểm tra giấy tờ, quy định nhập cảnh áp dụng cho quốc tịch của bạn, ngày bay và yêu cầu hành lý trước khi mua dịch vụ không hoàn hủy. Dành thời gian dự phòng giữa chặng đường bộ và chuyến bay.','Lưu địa chỉ lưu trú, mã đặt chỗ và số liên hệ để xem ngoại tuyến. Xác nhận tổng giá, số khách, thuế, giờ nhận phòng, điều kiện thay đổi và phương án di chuyển. Không dùng một checklist chung để thay thế quy định hiện hành của nhà cung cấp.'),
('Cuối tuần ở Đà Nẵng: một lịch trình nhẹ cho hai ngày','Ngày đầu có thể dành cho một đoạn dạo biển phù hợp điều kiện thực tế, cà phê và nghỉ nhận phòng. Buổi chiều chọn một cụm điểm nội đô thay vì di chuyển liên tục giữa nhiều khu vực.','Ngày thứ hai để một hoạt động chính, sau đó dành thời gian ăn uống và chuẩn bị chặng về. Nếu muốn thêm Hội An hoặc một tour xa, giảm bớt các hoạt động khác. Lịch này là gợi ý tự túc, không gồm vé hoặc dịch vụ.'),
('Ở gần biển Mỹ Khê: cách kiểm tra vị trí khách sạn','Đối chiếu địa chỉ khách sạn với lối đi ra biển, đường cần băng qua và những điểm bạn sẽ ghé. Khoảng cách thẳng trên bản đồ không thay thế tuyến đi bộ thực tế, đặc biệt khi đi cùng trẻ nhỏ hoặc người lớn tuổi.','Đọc nhận xét gần đây về tiếng ồn và xác nhận đúng loại phòng. Một phòng nhìn biển không đồng nghĩa khách sạn nằm ngay bãi biển; tên hoặc hình minh họa cũng không xác nhận view của gói phòng bạn chọn.'),
('Khách sạn ven biển hay trung tâm Đà Nẵng: chọn theo lịch đi','Nếu ưu tiên thời gian ngoài biển, hãy kiểm tra tuyến đi bộ và các dịch vụ quanh nơi ở. Nếu có nhiều lịch hẹn, ăn uống hoặc tham quan nội đô, cân nhắc phương án thuận tiện cho những điểm đó.','Tính chi phí xe và thời gian di chuyển cho cả chuyến đi. So sánh bằng cùng ngày, số khách và điều kiện hủy; không mặc định khách sạn ven biển luôn đắt hơn hoặc cơ sở trung tâm luôn yên tĩnh hơn.'),
('Chọn khách sạn tốt cho nhu cầu của bạn: những tiêu chí cần đọc','Bắt đầu từ địa chỉ, loại giường, số người được ở và giờ nhận phòng. Tiếp theo là các tiện nghi thực sự cần như điều hòa, Wi-Fi hoặc bữa sáng; xác nhận từng yếu tố trong hạng phòng, không chỉ xem ảnh quảng cáo.','Nhận xét mới có thể giúp bạn đặt câu hỏi rõ hơn về vệ sinh, tiếng ồn hoặc quy trình nhận phòng. Những đánh giá đó không thay thế điều kiện chính thức của gói đã đặt. Lưu xác nhận trước ngày khởi hành.'),
('Một ngày nghỉ dưỡng ở Việt Nam: kiểm tra gói resort trước khi đặt','Nếu muốn dành nhiều thời gian tại nơi ở, hãy ưu tiên các dịch vụ bạn thực sự dùng. Kiểm tra giờ hoạt động, quy định tiếp cận và các khoản phụ phí trước khi chọn phòng.','Hình minh họa hồ bơi hoặc cảnh biển là cảm hứng chung, không xác nhận một cơ sở có các tiện ích đó. Đối chiếu ảnh phòng và thông tin nhà cung cấp; hỏi rõ bữa ăn, đưa đón và chính sách khi lịch đi thay đổi.'),
('Lưu trú boutique ở Hội An: kiểm tra phố cổ và phương tiện','Xem địa chỉ cơ sở so với những khu vực bạn muốn ghé, rồi kiểm tra đường đi bộ hoặc phương tiện buổi tối. Tên có chữ Hội An không bảo đảm nơi ở sát phố cổ.','Nếu quan tâm sân vườn, ban công hoặc một phong cách phòng cụ thể, xác nhận đúng hạng được bán. Hỏi thêm giờ nhận phòng, giữ hành lý và cách về sau hoạt động buổi tối thay vì suy ra từ ảnh minh họa.'),
('Các lỗi đặt phòng dễ tránh: nhìn tổng tiền và đúng loại phòng','So sánh cùng ngày, số khách và hạng giường. Đọc tổng tiền sau thuế, khoản đặt cọc, bữa ăn và thời hạn hủy. Hai giá đầu trang có thể áp dụng cho điều kiện rất khác nhau.','Kiểm tra tên cơ sở, địa chỉ, thông tin khách và yêu cầu đặc biệt trước thanh toán. Không mặc định yêu cầu phòng liền nhau, nhận sớm hoặc view đẹp đã được chấp nhận nếu chưa có xác nhận.'),
('Đà Nẵng cho cặp đôi: lịch đi chậm và cách chọn chỗ ở','Chọn một hoạt động chính mỗi ngày, để thời gian ăn uống và nghỉ ngơi. Một buổi dạo biển hoặc ven sông cần được điều chỉnh theo thời tiết, sức khỏe và giờ di chuyển.','Nếu view, ban công hay sự yên tĩnh là ưu tiên, đọc đúng mô tả hạng phòng và nhận xét gần đây. Ảnh bìa là cảm hứng du lịch, không cam kết một căn phòng hoặc dịch vụ lãng mạn cụ thể.'),
('Đi cùng gia đình: kiểm tra phòng, bữa ăn và phương tiện','Xác nhận sức chứa phòng, tuổi trẻ em, giường phụ và phụ phí theo đúng thành viên. Nếu quan tâm hồ bơi hoặc khu vui chơi, kiểm tra quy định giám sát, giờ mở cửa và điều kiện sử dụng.','Tính thời gian nghỉ giữa các hoạt động, chọn phương tiện phù hợp với hành lý và hỏi trước về ghế trẻ em khi cần. Không đặt lịch quá dày chỉ để khớp một danh sách điểm tham quan.'),
('Lưu trú tiết kiệm hay cao cấp ở Đà Nẵng: so sánh theo nhu cầu','Dùng cùng tiêu chí khi so sánh: tổng tiền, thời gian di chuyển, sự thoải mái cần có và điều kiện hủy. Một mức giá cao hơn không tự động mang lại giá trị tốt hơn cho mọi chuyến đi.','Chỉ tính các tiện ích có trong gói và bạn thực sự sẽ sử dụng. Nếu ưu tiên khám phá cả ngày, việc dành ngân sách cho phương tiện hoặc trải nghiệm có thể quan trọng hơn dịch vụ trong khách sạn.'),
('Tạo shortlist khách sạn: ba lựa chọn, một bộ tiêu chí','Lưu ba phương án có vị trí khác nhau, sau đó đối chiếu bằng cùng ngày ở, số khách và điều kiện phòng. Có thể dùng danh sách yêu thích trên website như bước so sánh ban đầu.','Trước khi quyết định, kiểm tra nhận xét mới, tổng thuế phí, hạn hủy và thời gian đến những điểm ưu tiên. Danh sách gợi ý không phải cam kết giảm giá hoặc xếp hạng bán chạy hiện tại.'),
('Đi Bà Nà Hills trong ngày: vé, thời tiết và xe đón','Kiểm tra phạm vi vé, điểm đón, thời lượng di chuyển và những hoạt động được bao gồm. Cầu Vàng là một điểm nổi bật của khu vực, nhưng không có nghĩa mọi vé hay tour đều có cùng lịch tham quan.','Chọn trang phục phù hợp điều kiện núi, xem dự báo gần ngày đi và thông báo vận hành của nhà cung cấp. Chừa thời gian nghỉ và hỏi rõ chính sách thay đổi khi thời tiết ảnh hưởng hoạt động.'),
('Hội An sau hoàng hôn: đi bộ, ăn uống và đường về','Chọn một quãng dạo phố hoặc ven sông phù hợp, để thời gian ăn uống và nghỉ chân. Kiểm tra quy định ra vào từng điểm và điều kiện hoạt động thực tế thay vì mặc định mọi khu vực đều giống nhau.','Nếu có thuyền, tour hoặc đưa đón, hỏi rõ bến và điểm hẹn, thời lượng, dịch vụ bao gồm và hạn hủy. Lưu cách về nơi ở buổi tối; ánh đèn và điều kiện chụp ảnh có thể thay đổi theo ngày.'),
('Một ngày tìm hiểu Huế: chọn một cụm di sản vừa sức','Dành đủ thời gian cho một cụm điểm, chẳng hạn khu Đại Nội, thay vì ghép nhiều lăng tẩm trong một buổi. Xem phạm vi vé và giờ vào cửa từ nguồn chính thức.','Với chuyến đi từ Đà Nẵng, tính cả thời gian xe và những khoảng nghỉ. Ăn mặc phù hợp ở nơi thờ tự, xem thời tiết và kiểm tra thành phần món ăn nếu có nhu cầu đặc biệt.'),
('Du lịch Việt Nam qua ẩm thực: chọn món và trải nghiệm phù hợp','Mỗi vùng có cách chế biến và nguyên liệu riêng. Hãy hỏi thành phần, khẩu phần và giá trước khi gọi; nếu có dị ứng hoặc chế độ ăn đặc biệt, trao đổi rõ với người bán.','Một tour đi bộ ẩm thực cần được kiểm tra điểm hẹn, thời lượng, ngôn ngữ hướng dẫn và đồ ăn bao gồm. Đừng mặc định mọi món trong ảnh minh họa đều xuất hiện trong một tour cụ thể.'),
('Đi chậm ở miền Trung: để khoảng trống cho hành trình','Chọn một trải nghiệm có ý nghĩa cho mỗi buổi, sau đó để thời gian cà phê, nghỉ chân hoặc điều chỉnh theo thời tiết. Việc bớt điểm đôi khi giúp bạn dành nhiều thời gian hơn cho nơi thực sự quan tâm.','Nhóm các điểm gần nhau theo tuyến đường thực tế, không chỉ theo ảnh hoặc khoảng cách thẳng. Với chuyến xa, so sánh thời gian di chuyển với khoảng thời gian còn lại trước chặng về.'),
('Miền Trung ngoài bãi biển: di sản, bảo tàng và nghề thủ công','Có thể ghép một buổi tìm hiểu kiến trúc, bảo tàng hoặc nghề thủ công vào chuyến nghỉ biển. Kiểm tra địa chỉ, giờ mở cửa và điều kiện tham gia trước khi đi.','Xin phép trước khi chụp người dân hoặc không gian riêng, làm theo nội quy và không mặc định khách được vào mọi khu vực sản xuất. Nếu mua tour, xác nhận điểm dừng thực tế thay vì dựa vào một ảnh collage.'),
('Chọn hoạt động bình minh hay hoàng hôn cho chuyến Đà Nẵng','Cân nhắc giờ ngủ, sức khỏe, phương tiện và dự báo gần ngày đi. Ánh sáng dịu hoặc một cảnh hoàng hôn đẹp không được bảo đảm; thời tiết, mùa và tầm nhìn có thể làm trải nghiệm khác ảnh minh họa.','Lưu đường đi và phương án về, đặc biệt khi khởi hành sớm hoặc kết thúc muộn. Hoạt động biển cần tuân thủ khu vực được phép, cảnh báo và hướng dẫn của đơn vị tổ chức.'),
('Lên lịch tour trong ngày có khoảng linh hoạt','Đọc điểm đón, giờ có mặt, thời lượng, ngôn ngữ hướng dẫn và nội dung bao gồm. Nếu đi cùng trẻ nhỏ hoặc người lớn tuổi, hỏi rõ mức đi bộ và phương án nghỉ.','Giữ khoảng đệm trước lịch hẹn hoặc chuyến bay tiếp theo. Kiểm tra hạn hủy, cách liên lạc và thay đổi do thời tiết; không ghép nhiều vé không hoàn hủy trong cùng một ngày chỉ vì tên điểm nghe gần nhau.'),
('Bay đến Đà Nẵng: sân bay, hành lý và giờ đến','Đối chiếu sân bay đi và đến, nhà ga, giờ địa phương và hành lý của đúng hạng vé. So sánh tổng chi phí, bao gồm xe sân bay, thay vì chỉ nhìn giá ban đầu.','Nếu đến muộn, xác nhận nhận phòng trễ và cách liên lạc với nơi ở. Với chuyến nối, để thời gian dự phòng cho thủ tục và việc chuyển hành lý, không dùng một khoảng nối cố định cho mọi trường hợp.'),
('Khám phá Việt Nam bằng tàu hỏa: chọn tuyến và loại chỗ','Kiểm tra đúng nhà ga, giờ khởi hành, loại chỗ hoặc giường và quy định hành lý của vé. Tuyến đường sắt có thể là một phần trải nghiệm, nhưng cảnh nhìn thấy phụ thuộc lịch chạy, vị trí chỗ và điều kiện thực tế.','Lưu mã vé và hướng dẫn lên tàu để xem ngoại tuyến, dự trù xe từ ga đến nơi ở. Link Trip.com chung mở bước chọn dịch vụ; bạn cần tự kiểm tra tuyến và tình trạng vé, không có vé tàu cụ thể được chọn sẵn.'),
('Từ Đà Nẵng đến Huế: so sánh đường sắt và đường bộ','So sánh giờ đi, điểm đón hoặc nhà ga, hành lý và thời gian đến địa chỉ thực tế. Một hành trình ngắm cảnh cần đủ thời gian di chuyển; không mặc định mọi phương tiện đi cùng một tuyến hoặc có các điểm dừng giống nhau.','Nếu chọn ô tô, hỏi rõ xe tự lái hay có tài xế và điều kiện dừng nghỉ. Nếu chọn tàu, xác nhận tuyến và loại chỗ. Để khoảng đệm trước hoạt động hoặc chuyến bay sau đó.'),
('Đặt xe sân bay: kiểm tra chuyến đến và điểm hẹn','Xác nhận số chuyến bay, nhà ga, giờ đón, số khách và lượng hành lý. Đọc thời gian chờ, phụ phí đi đêm, cách liên hệ tài xế và yêu cầu ghế trẻ em nếu có.','Hỏi quy trình khi chuyến bay trễ hoặc thay đổi nhà ga. Dùng đúng tên cơ sở và địa chỉ nhận phòng; một tên thương hiệu chung có thể không đủ để xác định nơi trả khách.'),
('Ý tưởng đi đường bộ miền Trung: tuyến vừa sức và chặng nghỉ','Chọn phương tiện phù hợp giấy tờ, sức khỏe và điều kiện đường đi. Phân biệt thuê xe tự lái với xe có tài xế, đọc bảo hiểm, nhiên liệu, đặt cọc và quy định trả xe.','Chừa thời gian dừng nghỉ, không tự lái khi mệt và tuân thủ hướng dẫn địa phương. Hình đường ven biển là cảm hứng tuyến đi, không xác nhận điều kiện giao thông hoặc một điểm dừng cụ thể trong gói thuê.'),
('Đi Đà Nẵng mùa nào: chọn theo hoạt động và dự báo','Thời tiết thay đổi giữa các thời điểm và từng năm. Chọn lịch theo điều bạn muốn làm, sau đó kiểm tra dự báo ngắn hạn, thông báo địa phương và điều kiện hủy trước khi đặt hoạt động ngoài trời.','Giữ một phương án trong nhà hoặc ngày nghỉ nếu điều kiện không phù hợp. Một poster nắng đẹp không phải dự báo; các cảnh biển hoặc núi cần được đánh giá bằng thông tin gần ngày đi.'),
('Bắt đầu chuyến Việt Nam: từ ý tưởng đến lịch trình thực tế','Chốt vùng trọng tâm, số đêm và các chặng đến trước, rồi chọn một vài trải nghiệm ưu tiên. So sánh khách sạn và phương tiện theo cùng ngày, số khách và điều kiện.','Lưu xác nhận, địa chỉ, phương án dự phòng và khoảng đệm trước chặng về. Website giúp bạn tìm ý tưởng và mở dịch vụ phù hợp; giá, chỗ trống, vé và thanh toán cần được xác nhận trên Trip.com hoặc nhà cung cấp.')]
EN_NOTES=[
'Choose a manageable region, map your priorities and leave transfer buffers before booking. This independent guide helps you shortlist services; Trip.com handles the actual booking and payment conditions.',
'Compare transport and accommodation around your actual itinerary. A general partner link does not preselect a rail route, seat or departure time; confirm those separately with the seller.',
'Map beach time, the Han River area and any separate visits to Hoi An or Hue. A hotel name or illustration does not establish walking distance to your stops.',
'Check current entry rules for your nationality, transport dates, baggage, addresses and cancellation deadlines. Keep confirmations and contact details available offline.',
'Use day one for arrival, one beach or city outing and rest. Leave one main activity for day two, reducing other plans if you add a longer day trip.',
'Check the actual route to the beach, road crossings and recent noise reports. A sea-view room and a beachfront property are different booking choices.',
'Compare total transport time for your plans rather than assuming either location type is always cheaper, quieter or more convenient.',
'Confirm the room, occupancy, bed type and amenities you need in the actual package. Read recent reviews to frame questions, not as a substitute for booking conditions.',
'Check facility access, opening hours, meals and supplements. The pool or room in an AI illustration is generic inspiration, not evidence about a particular property.',
'Confirm distance to your intended Hoi An stops and evening transport. A town name in a listing does not establish proximity to the old town.',
'Compare the same dates, guest count and room conditions, including taxes and deposits. Reconfirm special requests such as adjacent rooms or early check-in.',
'Leave one main activity per day and time for meals and rest. Verify the exact room view or balcony if it matters; a romantic illustration is not a room guarantee.',
'Check child ages, occupancy, extra beds, meals and supervision requirements. Plan breaks and confirm suitable luggage capacity and child-seat arrangements.',
'Compare the complete journey cost and facilities you will actually use. A higher room price is not automatically better value for every itinerary.',
'Compare three stays using consistent dates, occupancy and cancellation terms. Reference categories and a personal shortlist are not live discounts or sales rankings.',
'Confirm ticket scope, pickup, travel time and operating notices. Mountain conditions can affect plans; check the short-range forecast and provider policies.',
'Choose a manageable evening walk and arrange the return to your accommodation. Confirm meeting points, duration and inclusions for any boat trip or guided activity.',
'Choose one main heritage cluster and check its actual admission scope. Include travel time from Da Nang and dress appropriately at places of worship.',
'Ask about ingredients, portions and prices, especially for allergies. For food walks, confirm guide language, meeting point and included dishes.',
'Group stops by real transport routes and leave time for rest or changing weather. A shorter checklist can give more time to the places you care about.',
'Check opening hours and permission before entering craft or private spaces. A collage does not prove that every depicted place is included in a tour.',
'Choose an outing around your energy, transport and actual conditions. Good light or clear views are not guaranteed; follow local safety notices.',
'Confirm pickup, duration, walking level and cancellation rules. Leave a buffer before an onward flight or another time-specific booking.',
'Check the airport, terminal, local times and baggage for your fare. Include airport transport in the total cost and arrange late check-in when needed.',
'Confirm the actual station, departure, seat or berth and baggage rules. Keep the ticket offline and plan the connection from the station to your stay.',
'Compare rail and road options by real pickup points, schedule and luggage. Confirm the route and stops rather than assuming every service follows the same scenic alignment.',
'Confirm the flight number, terminal, pickup time and waiting allowance. Read delay policies and ask about luggage, child seats and night supplements.',
'Distinguish self-drive from chauffeur services and check documents, insurance, fuel, deposits and return location. Plan breaks and never drive while tired.',
'Pick activities first, then check short-range forecasts and local notices. Keep a rainy-day alternative; a sunny poster does not predict travel-day conditions.',
'Choose your region and nights first, then compare stays and transport for actual dates. Keep booking references, addresses and a realistic buffer for departure.']
assert len(VI)==len(EN_NOTES)==30
SOURCE=('Vietnam Tourism — Plan your trip','https://vietnam.travel/plan-your-trip')
def register(content,languages,slugs,sources,details):
    for i,item in enumerate(DAYS):
        slugs.append((item['category'],item['slug']));refs=[SOURCE]
        if item['day']==17:refs.append(('UNESCO — Hoi An Ancient Town','https://whc.unesco.org/en/list/948/'))
        if item['day']==18:refs.append(('UNESCO — Complex of Hué Monuments','https://whc.unesco.org/en/list/678/'))
        sources.append(refs)
        services=['hotels','tours','flights','transfers','cars'] if item['service']=='home' else [item['service']]
        details[item['slug']]={'booking':item['affiliate_url'],'booking_services':services,'poster_download':True,'campaign_day':item['day'],'campaign_image':item['image']}
        for lang in languages:
            u=content[lang]['ui'];vi_title,vi_a,vi_b=VI[i]
            if lang=='vi':title=vi_title;intro=vi_a;sections=[('Gợi ý lên kế hoạch',vi_b),('Trước khi đặt dịch vụ','Kiểm tra địa chỉ, giờ hoạt động, tổng giá và điều kiện hủy theo ngày bạn đi. Đây là nội dung hướng dẫn và hình minh họa AI, không phải đánh giá trực tiếp hay xác nhận ưu đãi hiện tại.')]
            elif lang=='en':title=item['title_en'];intro=item['summary_en'];sections=[('Make the idea practical',EN_NOTES[i]),('Before booking','Check current opening hours, the actual route, included services and cancellation conditions. These are independent planning ideas and AI illustrations, not firsthand hotel reviews or live package offers.')]
            else:
                title=item['title_en']+' · '+u[2];intro=u[18];sections=[(u[2],u[13])]
                details[item['slug']]['source_summary_en']=item['summary_en']+' '+EN_NOTES[i]
            content[lang]['articles'].append([title,intro,sections])
